-- Packs d'ampoules halogènes « effet xénon » : nommés pour ce qu'ils sont.
--
-- Les packs par véhicule reprennent le contenu du pack que le partenaire vend
-- pour le même véhicule et le même emplacement. Pour 1642 d'entre eux
-- (1 625 phares, 9 antibrouillards, 8 feux de jour), ce pack est son pack
-- « effet xénon » : des ampoules halogènes à lumière blanche, pas des LED. Ils
-- avaient pourtant été créés sous le nom « Pack LED … ». Voir src/lib/effet-xenon.ts.
--
-- La migration ne touche qu'aux fiches restées telles que l'import les a
-- écrites (nom inchangé) : une fiche renommée au back-office est laissée
-- comme elle est. Les textes écrits à la main (description, titre et
-- description de référencement) sont gardés ; seuls ceux de l'import sont
-- réécrits. L'adresse des fiches (slug) ne change pas.
--
-- La liste vient du relevé (prisma/packs-vehicule*.json), filtré par
-- `vignetteEffetXenon` ; tests/effet-xenon.test.ts vérifie qu'elle n'a pas
-- dérivé.

CREATE TEMP TABLE "_packs_effet_xenon" (
  "slug" TEXT PRIMARY KEY,
  "ancien" TEXT NOT NULL,
  "nom" TEXT NOT NULL,
  "description" TEXT NOT NULL
);


-- Les variantes d'abord : elles se retrouvent par le nom encore intact du produit.
UPDATE "ProductVariant" pv
SET "name" = v."nom", "updatedAt" = CURRENT_TIMESTAMP
FROM "Product" p
JOIN "_packs_effet_xenon" v ON v."slug" = p."slug"
WHERE pv."productId" = p."id" AND p."name" = v."ancien" AND pv."name" = v."ancien";

-- Textes alternatifs des visuels : la vignette porte le nom du pack, les rendus
-- disaient « en LED blanche ».
UPDATE "Media" m
SET "alt" = REPLACE(
  REPLACE(
    REPLACE(m."alt", ' en LED blanche.', ' en ampoules effet xénon.'),
    '; LED en bas, lumière blanche.', '; ampoules effet xénon en bas, lumière blanche.'
  ),
  v."ancien", v."nom"
)
FROM "ProductMedia" pm
JOIN "Product" p ON p."id" = pm."productId"
JOIN "_packs_effet_xenon" v ON v."slug" = p."slug"
WHERE m."id" = pm."mediaId" AND m."alt" IS NOT NULL AND p."name" = v."ancien";

-- La fiche elle-même.
UPDATE "Product" p
SET
  "name" = v."nom",
  "description" = CASE
    WHEN p."description" IS NULL OR p."description" LIKE 'Pack LED pour les %' THEN v."description"
    ELSE p."description" END,
  "metaTitle" = CASE
    WHEN p."metaTitle" IS NULL OR p."metaTitle" = v."ancien" OR p."metaTitle" LIKE '% — LUMERA' THEN v."nom"
    ELSE p."metaTitle" END,
  "metaDescription" = CASE
    WHEN p."metaDescription" IS NULL OR p."metaDescription" LIKE 'Pack LED pour les %' THEN v."description"
    ELSE p."metaDescription" END,
  "body" = REPLACE(
    REPLACE(p."body", 'Pack d''éclairage LED composé pour la ', 'Pack d''ampoules halogènes effet xénon composé pour votre '),
    'Pack d''éclairage LED composé pour votre ', 'Pack d''ampoules halogènes effet xénon composé pour votre '
  ),
  "updatedAt" = CURRENT_TIMESTAMP
FROM "_packs_effet_xenon" v
WHERE p."slug" = v."slug" AND p."name" = v."ancien";

-- Rangement : de la rubrique LED à la rubrique « Effet xénon », seulement si
-- elle existe (sinon les fiches gardent leur rangement actuel).
DELETE FROM "ProductCategory" pc
USING "Product" p, "_packs_effet_xenon" v, "Category" c
WHERE pc."productId" = p."id" AND p."slug" = v."slug" AND p."name" = v."nom"
  AND pc."categoryId" = c."id" AND c."slug" IN ('phares-led', 'antibrouillards', 'feux-de-jour')
  AND EXISTS (SELECT 1 FROM "Category" WHERE "slug" = 'ampoules-effet-xenon');

SELECT p."id", c."id", 0
FROM "Product" p
JOIN "_packs_effet_xenon" v ON v."slug" = p."slug"
CROSS JOIN "Category" c
WHERE c."slug" = 'ampoules-effet-xenon' AND p."name" = v."nom"
ON CONFLICT DO NOTHING;

DROP TABLE "_packs_effet_xenon";
